import random

class Voter:
    def __init__(self, voter_id, vote):
        self.voter_id = voter_id
        self.vote = vote

class VotingSystem:
    def __init__(self, candidates, max_votes=100):
        self.candidates = candidates
        self.max_votes = max_votes
        self.current_votes = {}  # Map candidate ID to total votes
        self.voter_list = []

    def add_voter(self, voter_id, vote):
        voter = Voter(voter_id, vote)
        self.voter_list.append(voter)

    def register_vote(self, voter_id):
        for voter in self.voter_list:
            if voter.voter_id == voter_id:
                return True
        return False

    def get_vote(self, candidate_id):
        candidates = self.candidates.copy()
        return candidates.pop(candidate_id)

    def update_vote_counts(self):
        for voter in self.voter_list:
            if voter.vote:
                for candidate in self.candidates:
                    if voter.vote == candidate:
                        self.current_votes[candidate] += 1

    def display_results(self):
        for candidate in self.candidates:
            print(f"{candidate}: {self.current_votes.get(candidate, 0)}")


class Hacker:
    def __init__(self, target_system, attack_level, vulnerability_rate=0.1):
        self.target_system = target_system
        self.attack_level = attack_level
        self.vulnerability_rate = vulnerability_rate
        self.attack_attempts = 0
        self.successes = 0

    def perform_attack(self, system):
        print(f"Hacking the system: {system.target_system}...")
        if random.random() < system.attack_level * self.vulnerability_rate:
            system.update_vote_counts()
            self.successes += 1
            print("Hack Successful!")
        else:
            print("Attack Failed.")
